CREATE TABLE "Internship" (id UUID PRIMARY KEY,"internId" UUID NOT NULL REFERENCES "Person"(id) ON DELETE RESTRICT,"mentorId" UUID NOT NULL REFERENCES "Person"(id) ON DELETE RESTRICT,"departmentId" UUID NOT NULL REFERENCES "Department"(id) ON DELETE RESTRICT,"startDate" DATE NOT NULL,"endDate" DATE NOT NULL,objective TEXT NOT NULL CHECK(length(trim(objective)) BETWEEN 1 AND 5000),status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','COMPLETED','CANCELED')),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL,CHECK("internId"<>"mentorId"),CHECK("endDate">="startDate"));
CREATE UNIQUE INDEX "Internship_one_active" ON "Internship"("internId") WHERE status='ACTIVE';
CREATE INDEX "Internship_mentorId_status_idx" ON "Internship"("mentorId",status);
CREATE TABLE "LearningMilestone" (id UUID PRIMARY KEY,"internshipId" UUID NOT NULL REFERENCES "Internship"(id) ON DELETE RESTRICT,title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200),description TEXT NOT NULL,"dueDate" DATE NOT NULL,status TEXT NOT NULL DEFAULT 'PLANNED' CHECK(status IN ('PLANNED','ACTIVE','SUBMITTED','COMPLETED')),"completedAt" TIMESTAMPTZ,"completedBy" UUID REFERENCES "Person"(id) ON DELETE RESTRICT,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL);
CREATE INDEX "LearningMilestone_internshipId_dueDate_idx" ON "LearningMilestone"("internshipId","dueDate");
CREATE TABLE "MilestoneTask" ("milestoneId" UUID NOT NULL REFERENCES "LearningMilestone"(id) ON DELETE RESTRICT,"taskId" UUID NOT NULL REFERENCES "Task"(id) ON DELETE RESTRICT,PRIMARY KEY("milestoneId","taskId"));
CREATE TABLE "WeeklyFeedback" (id UUID PRIMARY KEY,"internshipId" UUID NOT NULL REFERENCES "Internship"(id) ON DELETE RESTRICT,"authorId" UUID NOT NULL REFERENCES "Person"(id) ON DELETE RESTRICT,"updatedBy" UUID NOT NULL REFERENCES "Person"(id) ON DELETE RESTRICT,"weekStart" DATE NOT NULL,strengths TEXT NOT NULL,improvements TEXT NOT NULL,"nextActions" TEXT NOT NULL,rating INTEGER CHECK(rating BETWEEN 1 AND 5),"ratingExplanation" TEXT,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL,UNIQUE("internshipId","weekStart"),CHECK(rating IS NULL OR length(trim("ratingExplanation"))>0),CHECK(extract(isodow FROM "weekStart")=1));
DO $$ DECLARE n TEXT; BEGIN FOREACH n IN ARRAY ARRAY['Internship','LearningMilestone','MilestoneTask','WeeklyFeedback'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN EXECUTE format('REVOKE ALL ON %I FROM anon',n); END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN EXECUTE format('REVOKE ALL ON %I FROM authenticated',n); END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO encova_app',n); EXECUTE format('CREATE POLICY encova_server_access ON %I TO encova_app USING(true) WITH CHECK(true)',n); END IF;
 END LOOP; END $$;
